"use strict";function query(n){$.ajax({url:_global.root+"WorkFromHomeRequest/GetWorkFromHomeRequestGrid",type:"GET",dataType:"html",data:{year:$("#Year").val()},beforeSend:function(){n||$(".loading-process").fadeIn(300)},success:function(n){$("#work-from-home-request").html(n);bindMenuPending()},error:function(){alert(_messages.errorTryAgain)},complete:function(){n||$(".loading-process").fadeOut(300)}})}function initCreateUpdatePage(){var n=$("#successed").val();n==="true"&&confirm('<i class="icon-success mdi mdi-checkbox-marked-circle-outline"><\/i><p>Successfull!<\/p><p>Press OK to continue<\/p>',function(){document.location=_global.root+"WorkFromHomeRequest"})}function cancelRequest(n){confirm("<p>Are you sure you want to cancel this request?<\/p>",function(){$.post(_global.root+"WorkFromHomeRequest/Delete/"+n,function(t){t.IsSuccessful?($("#row_"+n).remove(),autoIndex()):alert(t.Message)})})}function processRequest(n,t){var i=$(t).attr("requestId");switch(n){case"edit":location.href=_global.root+"WorkFromHomeRequest/Edit/"+i;break;case"delete":cancelRequest(i)}}function bindMenuPending(){$.contextMenu({selector:".Pending",trigger:"left",build:function(n,t){return{callback:function(n){processRequest(n,t.currentTarget)},items:{edit:{name:"Edit",icon:"edit"},"delete":{name:"Delete",icon:"delete"}}}}})}$(document).ready(function(){if($(".form-create-update").length>0)initCreateUpdatePage();else{query(!0);$("#submit").on("click",function(){query(!1)})}});"use strict";